import{_ as s,o as r,c as t,a5 as a}from"./chunks/framework.B6tQOu6W.js";const n="/assets/logo.Bf6iBU3k.png",o="/assets/pma.k7DSbgHD.png",i="/assets/setup_wp.BqwF4B4z.png",l="/assets/bdd_wp.52AXOCcT.png",p="/assets/bdd_wp2.CxeynXS5.png",u="/assets/configuration_wp.exb-ClbS.png",d="/assets/wp_main_admin.CmHSQFL5.png",c="/assets/wp_page.BTi4pUCu.png",m="/assets/previsualiser.J312TNwa.png",w=JSON.parse(`{"title":"Installer & Configurer Wordpress","description":"Créer un site depuis zéro n'est pas la seule solution, en informatique nous avons également ce que nous appelons des CMS. Un CMS est un outil qui va nous fournir une base de code « Client & Administration »","frontmatter":{"description":"Créer un site depuis zéro n'est pas la seule solution, en informatique nous avons également ce que nous appelons des CMS. Un CMS est un outil qui va nous fournir une base de code « Client & Administration »"},"headers":[],"relativePath":"tp/cms/wordpress.md","filePath":"tp/cms/wordpress.md","lastUpdated":1640899309000}`),h={name:"tp/cms/wordpress.md"};function g(f,e,v,b,q,_){return r(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="installer-configurer-wordpress" tabindex="-1">Installer &amp; Configurer Wordpress <a class="header-anchor" href="#installer-configurer-wordpress" aria-label="Permalink to &quot;Installer &amp; Configurer Wordpress&quot;">​</a></h1><p>Créer un site depuis zéro n&#39;est pas la seule solution, en informatique nous avons également ce que nous appelons des CMS. Un CMS est un outil qui va nous fournir une base de code « Client &amp; Administration » pour créer un site tel que :</p><ul><li>Un site web.</li><li>Une boutique en ligne.</li><li>Un Blog.</li></ul><p>Pour toutes ces situations, vous avez la possibilité d&#39;installer, de configurer, de personnaliser un CMS.</p><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>Dans ce document nous allons voir l&#39;installation de Wordpress, sa configuration et sa personnalisation avec des plug-ins.</p><p><img src="'+n+'" alt="" loading="lazy"></p><h2 id="installer-wordpress" tabindex="-1">Installer Wordpress <a class="header-anchor" href="#installer-wordpress" aria-label="Permalink to &quot;Installer Wordpress&quot;">​</a></h2><p>L&#39;installation de la solution Wordpress est très simple elle se résume à</p><ul><li><a href="https://fr.wordpress.org/download/" target="_blank" rel="noreferrer">Télécharger Wordpress</a></li><li>Extraire Wordpress « dans votre un dossier sur votre serveur Apache » (htdocs)</li><li>Ouvrir votre navigateur afin de configurer le Wordpress fraichement téléchargé</li></ul><h2 id="creer-la-base-de-donnees" tabindex="-1">Créer la base de données <a class="header-anchor" href="#creer-la-base-de-donnees" aria-label="Permalink to &quot;Créer la base de données&quot;">​</a></h2><p>La première étape va être de créer une base de données « vide ». Celle-ci sera entièrement configurée / rempli par l&#39;installeur de Wordpress.</p><ul><li><a href="http://localhost/phpmyadmin/" target="_blank" rel="noreferrer">Ouvrir phpMyAdmin</a></li><li>Créer une nouvelle base de données nommée <code>wordpress</code></li></ul><p><img src="'+o+'" alt="phpMyAdmin" loading="lazy"></p><h2 id="configurer-wordpress" tabindex="-1">Configurer Wordpress <a class="header-anchor" href="#configurer-wordpress" aria-label="Permalink to &quot;Configurer Wordpress&quot;">​</a></h2><p>Wordpress intègre une interface « pas à pas » pour configurer votre nouveau CMS. Cette interface va nous permettre de configurer :</p><p><img src="'+i+'" alt="Première étape de l&#39;installation" loading="lazy"></p><h3 id="les-parametres-de-base-de-donnees" tabindex="-1">Les paramètres de base de données. <a class="header-anchor" href="#les-parametres-de-base-de-donnees" aria-label="Permalink to &quot;Les paramètres de base de données.&quot;">​</a></h3><p>Nous avons créé une base de données nommée <code>wordpress</code>, nous allons donc indiquer ceci à l&#39;installeur de Wordpress :</p><p><img src="'+l+'" alt="Base de données Wordpress" loading="lazy"></p><p>Si tout se passe bien, vous devez avoir :</p><p><img src="'+p+'" alt="Installation réussie" loading="lazy"></p><div class="tip custom-block"><p class="custom-block-title">Lancer l&#39;installation</p><p>Pour lancer l&#39;installation, il suffit de cliquer sur « Run the Installation ». À cette étape Wordpress va créer l&#39;ensemble de la base de données.</p><p>Soyez curieux ! Je vous invite <strong>fortement</strong> <a href="http://localhost/phpmyadmin/db_structure.php?server=1&amp;db=wordpress" target="_blank" rel="noreferrer">à regarder les tables créées par Wordpress</a></p></div><h3 id="configurer-votre-wordpress" tabindex="-1">Configurer votre Wordpress <a class="header-anchor" href="#configurer-votre-wordpress" aria-label="Permalink to &quot;Configurer votre Wordpress&quot;">​</a></h3><p>Votre Wordpress est maintenant installé, il nous reste maintenant à spécifier quelques paramètres :</p><ul><li>Le nom du site.</li><li>Le nom et le mot de passe de l&#39;administrateur.</li><li>Votre email « d&#39;administrateur ».</li><li>Si votre Wordpress doit être indexé par les moteurs de recherche.</li></ul><p><img src="'+u+'" alt="Configuration de WP" loading="lazy"></p><p>Une fois installé vous serez redirigé vers la partie d&#39;admin de Wordpress.</p><div class="tip custom-block"><p class="custom-block-title">Et voilà !</p><p>Et oui c&#39;est tout ! Votre CMS est maintenant installé. 🥳</p><p><img src="'+d+'" alt="Wordpress c&#39;est ça" loading="lazy"></p></div><h2 id="installer-un-theme" tabindex="-1">Installer un thème <a class="header-anchor" href="#installer-un-theme" aria-label="Permalink to &quot;Installer un thème&quot;">​</a></h2><p>Wordpress intègre un système permettant de télécharger en quelques clics un thème. Vous trouverez ça dans le menu « Apparence »</p><p>Vous pouvez personnaliser le thème dans le menu « Apparence &gt; Personaliser »</p><p>Testons ensemble, nous allons installer un Thème nommé « Nouveau Blog ».</p><div class="tip custom-block"><p class="custom-block-title">Un instant</p><p>Chaque thème propose des personnalisations différentes. Donc le choix du thème de départ est plutôt important.</p></div><h2 id="installer-des-plug-ins" tabindex="-1">Installer des plug-ins <a class="header-anchor" href="#installer-des-plug-ins" aria-label="Permalink to &quot;Installer des plug-ins&quot;">​</a></h2><p>Votre Wordpress est maintenant configuré et est prêt à être personnalisé plus en profondeur. Vous pouvez installer des plug-ins qui permettront de le modifier en profondeur afin d&#39;en faire autre chose qu&#39;un simple blog.</p><p>Les extensions sont disponibles dans le menu « Extensions »</p><p>Je vous propose d&#39;installer un plug-in « très commun en ce moment » : <code>Cookie Notice</code></p><h2 id="creer-une-page" tabindex="-1">Créer une page <a class="header-anchor" href="#creer-une-page" aria-label="Permalink to &quot;Créer une page&quot;">​</a></h2><p>Un site sans page ce n’est pas un site non ? Avec Wordpress, vous pouvez créer très simplement des pages. La création de pages est complètement graphique et vous permet <strong>sans écrire de code</strong> la création de pages simple :</p><p><img src="'+c+'" alt="Création de pages" loading="lazy"></p><p>L&#39;éditeur est ce que l&#39;on appelle un WYSIWYG, il vous permettra de rédiger visuellement votre contenu (texte, mais également intégration de contenu provenant d&#39;autre site). Vous souhaitez ajouter une image ? Un simple Drag&amp;Drop est suffisant. Puissant hein !</p><p>✋ Au passage, le thème « Nouveau blog » que nous avons choisi tout à l&#39;heure, nous permet de mettre une « page » en « page d&#39;accueil » cette option est disponible dans « Apparence &gt; Personaliser ».</p><div class="tip custom-block"><p class="custom-block-title">et le responsive ?</p><p>Chez Wordpress ils ont également pensé à tout ça. Vous avez la possibilité de « Prévisualiser » votre page sous différents formats.</p><p><img src="'+m+'" alt="Visuel" loading="lazy"></p></div><h2 id="personnaliser-le-theme" tabindex="-1">Personnaliser le thème <a class="header-anchor" href="#personnaliser-le-theme" aria-label="Permalink to &quot;Personnaliser le thème&quot;">​</a></h2><p>Nous avons installé un thème oui, mais il ne vous convient peut-être pas à 100% ? Vous souhaitez peut-être le modifier pour le transformer légèrement. Pour ça vous avez quatre possibilités :</p><ul><li>Écrire une CSS personnalisée depuis l&#39;interface d&#39;admin.</li><li>Modifier le code source de thème depuis l&#39;interface d&#39;admin <strong>ou</strong> depuis le dossier thème dans le code source de wordpress.</li><li><a href="https://www.tutowp.fr/comment-creer-un-theme-enfant-sur-wordpress/" target="_blank" rel="noreferrer">Créer un thème enfant</a></li><li><a href="https://capitainewp.io/formations/developper-theme-wordpress/creer-base-theme-wordpress/" target="_blank" rel="noreferrer">Créer votre propre thème from scratch</a></li></ul><h2 id="et-la-maintenance" tabindex="-1">Et la maintenance ? <a class="header-anchor" href="#et-la-maintenance" aria-label="Permalink to &quot;Et la maintenance ?&quot;">​</a></h2><p>Maintenir un CMS est très important ! En effet un CMS est un développement « complexe », même si les développeurs de Wordpress ont travaillé avec des contraintes de sécurité importante un bug / faille est toujours possible.</p><p>C&#39;est dans cet objectif que Wordpress intègre un système automatique et simplifié de mise à jour, il suffit de cliquer sur le bon menu dans l&#39;interface.</p><div class="tip custom-block"><p class="custom-block-title">La sécurité avant tout</p><p>S&#39;il y a des mises à jour, ce <strong>n’est pas pour vous embêter</strong> mais pour <strong>vous protéger !</strong></p></div>',51)])])}const W=s(h,[["render",g]]);export{w as __pageData,W as default};
